// AMD module: block_pharos_teacher/activity-generator
// Handles the PHAROS-AI activity generator form: submit, display result, export.
define([], function () {
    'use strict';

    var _config = {};

    function init(config) {
        _config = config;

        var form    = document.getElementById('pharos-generator-form');
        var result  = document.getElementById('pharos-generator-result');
        var btnHtml = document.getElementById('pharos-export-html');
        var btnDocx = document.getElementById('pharos-export-docx');

        if (!form || !result) { return; }

        form.addEventListener('submit', function (e) {
            e.preventDefault();
            handleGenerate(form, result, btnHtml, btnDocx);
        });

        if (btnHtml) { btnHtml.addEventListener('click', function () { handleExport('html'); }); }
        if (btnDocx) { btnDocx.addEventListener('click', function () { handleExport('docx'); }); }
    }

    function handleGenerate(form, result, btnHtml, btnDocx) {
        var submitBtn = form.querySelector('[type="submit"]');
        var status    = document.getElementById('pharos-generator-status');
        var output    = document.getElementById('pharos-generator-output');
        var actions   = document.getElementById('pharos-generator-actions');

        setGenerating(true, submitBtn, status);
        result.hidden = true;
        if (actions) { actions.hidden = true; }

        var data = {
            sesskey:   _config.sesskey,
            courseid:  _config.courseId,
            level:     parseInt(form.querySelector('[name="level"]').value, 10),
            topic:     form.querySelector('[name="topic"]').value.trim(),
            objective: (form.querySelector('[name="objective"]') || {}).value || '',
            lang:      form.querySelector('[name="lang"]').value,
        };

        fetch(_config.ajaxUrl, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) })
        .then(function (res) {
            if (!res.ok) { return res.json().then(function (body) { throw new Error(body.error || 'HTTP ' + res.status); }); }
            return res.json();
        })
        .then(function (body) {
            if (body.error) { throw new Error(body.error); }
            if (!body.activity) { throw new Error('Empty response from server'); }
            result.dataset.activity = body.activity;
            result.dataset.lang     = data.lang;
            if (output) { output.textContent = body.activity; }
            result.hidden = false;
            if (actions) { actions.hidden = false; }
            if (btnHtml) { btnHtml.disabled = false; }
            if (btnDocx) { btnDocx.disabled = false; }
            result.scrollIntoView({ behavior: 'smooth', block: 'start' });
        })
        .catch(function (err) { showError(err.message || 'Error al generar la actividad.'); })
        .finally(function () { setGenerating(false, submitBtn, status); });
    }

    function handleExport(format) {
        var result   = document.getElementById('pharos-generator-result');
        var activity = result ? result.dataset.activity : '';
        var lang     = result ? (result.dataset.lang || 'es') : 'es';
        if (!activity) { return; }
        var data = { sesskey: _config.sesskey, courseid: _config.courseId, activity: activity, format: format, lang: lang };
        fetch(_config.exportUrl, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) })
        .then(function (res) {
            if (!res.ok) { throw new Error('Export failed: HTTP ' + res.status); }
            var disposition = res.headers.get('content-disposition') || '';
            var match = disposition.match(/filename[^;=\n]*=([('"].*?\2|[^;\n]*)/);
            var filename = match ? match[1].replace(/['"]/g, '') : ('pharos-activity.' + format);
            return res.blob().then(function (blob) { return { blob: blob, filename: filename }; });
        })
        .then(function (r) {
            var url = URL.createObjectURL(r.blob);
            var a = document.createElement('a');
            a.href = url; a.download = r.filename;
            document.body.appendChild(a); a.click(); document.body.removeChild(a); URL.revokeObjectURL(url);
        })
        .catch(function (err) { showError(err.message || 'Error al exportar la actividad.'); });
    }

    function setGenerating(loading, submitBtn, status) {
        if (submitBtn) { submitBtn.disabled = loading; }
        if (status) { status.hidden = !loading; }
    }

    function showError(message) {
        var errorEl = document.getElementById('pharos-generator-error');
        if (errorEl) { errorEl.textContent = message; errorEl.hidden = false; }
    }

    return { init: init };
});
